    'data_retention_title': {
      'tr': 'Veri Saklama',
      'en': 'Data Retention',
      'es': 'Retención de Datos',
      'fr': 'Conservation des Données',
      'de': 'Datenspeicherung',
      'ar': 'الاحتفاظ بالبيانات',
      'it': 'Conservazione dei Dati',
      'pt': 'Retenção de Dados',
      'ru': 'Хранение данных',
